export interface LawMeta {
  id: string;
  tab: string;
  name: string;
  short: string;
}

export interface Heading {
  h: number;
  l: string;
  n: string;
  id: string;
  a?: string[];
}
export interface Para {
  t: string;
  n?: string[];
  r?: 1;
}
export interface Article {
  k: string;
  p: Para[];
  rb?: string;
  r?: 1;
}
export type LawItem = Heading | Article;

export interface LawData {
  id: string;
  title: string;
  url: string;
  fetched: string;
  items: LawItem[];
}

export const isHeading = (it: LawItem): it is Heading => "h" in it;

// The catalog is generated by scripts/laws/build-laws.mjs from scripts/laws/laws.config.mjs.
import catalog from "../public/data/laws.json";

interface CatalogEntry {
  id: string;
  tab: string;
  short: string;
  topic: string;
  title: string;
  articles: number;
}
export const LAWS: LawMeta[] = (catalog as CatalogEntry[]).map((l) => ({
  id: l.id,
  tab: l.tab,
  name: l.topic,
  short: l.short,
}));
/** Tabs in catalog order: the codes first, then the areas of special legislation. */
export const TABS: string[] = [...new Set(LAWS.map((l) => l.tab))];
export const lawsInTab = (tab: string): LawMeta[] => LAWS.filter((l) => l.tab === tab);
export const lawMeta = (id: string): LawMeta => LAWS.find((l) => l.id === id) ?? LAWS[0];
